SOURCE = "Programme CAA du 16/11/2026, heures locales; disponibilité à confirmer"

def main():
    with connection() as conn:
        places={key(p['nom']):p['id'] for p in fetchall(conn,'SELECT id,nom FROM lieux')}
        grouped=defaultdict(list)
        for a,b,j,n,d,h,t in ROWS:
            grouped[a,b].append((j,n,d,h,t))
        for (a,b),slots in grouped.items():
            x,y=places.get(key(a)),places.get(key(b))
            if not x or not y:
                print('CAA: ville manquante',a,b)
                continue
            frequency=' ; '.join(dict.fromkeys(s[0] for s in slots))
            note='Horaires CAA (16/11/2026): '+ ' ; '.join(f'{j} {d}-{h} (vol {n}, durée {t})' for j,n,d,h,t in slots)
            existing=fetchall(conn,"SELECT id,note FROM liaisons WHERE depart_id=? AND arrivee_id=? AND mode='avion' AND LOWER(TRIM(operateur)) IN ('caa','compagnie africaine d''aviation')",(x,y))
            if existing:
                for row in existing:
                    old=row['note'] or ''
                    if note not in old:
                        execute(conn,"UPDATE liaisons SET frequence=?,note=?,verifie_le=?,source_info=? WHERE id=?",(frequency,(old+'\n'+note).strip(),'2026-11-16',SOURCE,row['id']))
            else:
                execute(conn,"INSERT INTO liaisons (mode,depart_id,arrivee_id,operateur,frequence,note,statut,publie,verifie_le,source_info) VALUES (?,?,?,?,?,?,?,?,?,?)",('avion',x,y,'CAA',frequency,note,'ok',0,'2026-11-16',SOURCE))

if __name__=='__main__':
    main()
